#include "Config.h"
Config::Config(QObject*p):QObject(p),s_("LemonadeAI","LemonadeAI"){key_=s_.value("gemini/key").toString();name_=s_.value("ai/name","Roblox Creator AI").toString();instructions_=s_.value("ai/instructions","Voce e um agente especializado em criar jogos Roblox. Planeje, use ferramentas reais, teste e corrija.").toString();}QString Config::apiKey()const{return key_;}QString Config::aiName()const{return name_;}QString Config::instructions()const{return instructions_;}void Config::setApiKey(const QString&v){key_=v.trimmed();emit changed();}void Config::setAiName(const QString&v){name_=v;emit changed();}void Config::setInstructions(const QString&v){instructions_=v;emit changed();}void Config::save(){s_.setValue("gemini/key",key_);s_.setValue("ai/name",name_);s_.setValue("ai/instructions",instructions_);s_.sync();emit changed();}
